GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Simulated annealing over model->GPU assignments with multiple restarts.

    1. Build a feasible greedy initial placement (best-fit by resulting KVPR).
    2. Repeatedly propose random single-model moves or pairwise swaps
       (only feasible ones), accepting uphill moves with probability
       exp(-delta/T) under a geometric cooling schedule.
    3. Keep the best assignment ever seen; return it as a placement dict.
    """

    import random

    n = len(models)
    w = [m.req_rate / m.slo for m in models]
    sz = [m.model_size for m in models]

    def kvpr_val(weight, free):
        return weight / free if free > 0 else float('inf')

    def greedy_assign(rng):
        """Greedy best-fit assignment; returns assign list or None."""
        assign = [-1] * n
        free = [float(GPU_MEM_SIZE)] * gpu_num
        weight = [0.0] * gpu_num
        idx = list(range(n))
        rng.shuffle(idx)
        idx.sort(key=lambda i: -w[i])
        for i in idx:
            best_g, best_v = -1, float('inf')
            for g in range(gpu_num):
                if sz[i] <= free[g]:
                    v = kvpr_val(weight[g] + w[i], free[g] - sz[i])
                    if v < best_v:
                        best_v, best_g = v, g
            if best_g < 0:
                return None
            assign[i] = best_g
            weight[best_g] += w[i]
            free[best_g] -= sz[i]
        return assign

    def stats(assign):
        weight = [0.0] * gpu_num
        free = [float(GPU_MEM_SIZE)] * gpu_num
        for i in range(n):
            g = assign[i]
            weight[g] += w[i]
            free[g] -= sz[i]
        if min(free) < 0:
            return None, float('inf')
        return (weight, free), max(kvpr_val(weight[g], free[g])
                                   for g in range(gpu_num))

    best_assign, best_val = None, float('inf')
    for restart in range(12):
        rng = random.Random(1000 + restart)
        assign = greedy_assign(rng)
        if assign is None:
            continue
        st, cur = stats(assign)
        if st is None:
            continue
        if cur < best_val:
            best_val, best_assign = cur, list(assign)
        T = max(cur, 1e-3)
        for step in range(4000):
            T *= 0.999
            if T < 1e-9:
                break
            i = rng.randrange(n)
            if rng.random() < 0.5 and gpu_num > 1:
                # move model i to a random other GPU
                g = rng.randrange(gpu_num)
                if g == assign[i] or sz[i] > st[1][g]:
                    continue
                new = list(assign)
                new[i] = g
            else:
                # swap two models' GPUs
                j = rng.randrange(n)
                if assign[i] == assign[j]:
                    continue
                new = list(assign)
                new[i], new[j] = new[j], new[i]
            st2, val2 = stats(new)
            if st2 is None:
                continue
            delta = val2 - cur
            if delta <= 0 or rng.random() < pow(2.718281828, -delta / T):
                assign, st, cur = new, st2, val2
                if cur < best_val:
                    best_val, best_assign = cur, list(assign)

    if best_assign is None:
        raise ValueError("Unable to place all models on the GPUs.")

    placement = {g: [] for g in range(gpu_num)}
    for i, g in enumerate(best_assign):
        placement[g].append(models[i])
    return placement

